struct Patch{void**slot;void*original;void*replacement;};std::array<Patch,32> patches{};std::atomic<size_t> patchCount{0};SRWLOCK patchLock=SRWLOCK_INIT;thread_local unsigned depth=0;
bool patch(void**table,size_t slot,void*replacement){AcquireSRWLockExclusive(&patchLock);auto count=patchCount.load();for(size_t i=0;i<count;++i)if(patches[i].slot==table+slot){bool same=patches[i].replacement==replacement;ReleaseSRWLockExclusive(&patchLock);return same;}if(count>=patches.size()){ReleaseSRWLockExclusive(&patchLock);return false;}DWORD old=0;if(!VirtualProtect(table+slot,sizeof(void*),PAGE_READWRITE,&old)){ReleaseSRWLockExclusive(&patchLock);return false;}void*before=table[slot],*actual=InterlockedCompareExchangePointer(table+slot,replacement,before);DWORD ignored=0;VirtualProtect(table+slot,sizeof(void*),old,&ignored);if(actual==before){patches[count]={table+slot,before,replacement};patchCount=count+1;}ReleaseSRWLockExclusive(&patchLock);return actual==before;}
